using System;using System.Data;using System.Data.SqlClient;using System.Globalization;using System.Web.UI.WebControls;
namespace Training.Manager{public partial class SessionReport:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string ManagerID{get{return Session["ManagerID"]==null?"":Session["ManagerID"].ToString();}}
protected void Page_Load(object s,EventArgs e){if(string.IsNullOrWhiteSpace(ManagerID)){Response.Redirect("~/Default.aspx");return;}if(!IsPostBack)BindGrid();}
private string LocationID(){DataTable d=obj.GetDataTable("SELECT TOP 1 TrainingLocationID FROM ManagerMaster WHERE ManagerID=@ManagerID AND ISNULL(ActiveStatus,'Y')='Y'",new SqlParameter[]{new SqlParameter("@ManagerID",ManagerID)});return d.Rows.Count==0?"":d.Rows[0][0].ToString();}
private void BindGrid(){string q="SELECT DISTINCT SM.SessionID,SM.TrainingID,TD.Batch,SM.SessionNo,SM.SessionName,SM.SessionDate,ISNULL(EBM.EmpName,TME.NameExternal) TrainerName FROM SessionMaster SM INNER JOIN TrainingDetails TD ON SM.TrainingID=TD.TrainingID INNER JOIN TrainingLocationMaster L ON TD.TrainingLocation=L.TrainingLocation INNER JOIN ManagerMaster M ON M.TrainingLocationID=L.TrainingLocationID LEFT JOIN EmpBasicMaster EBM ON SM.TrainerID=EBM.EmpID LEFT JOIN TrainerMaster TME ON SM.TrainerID=TME.TrainerID WHERE M.ManagerID=@ManagerID AND ISNULL(M.ActiveStatus,'Y')='Y' AND L.TrainingLocationID=@TrainingLocationID";var p=new System.Collections.Generic.List<SqlParameter>();p.Add(new SqlParameter("@ManagerID",ManagerID));p.Add(new SqlParameter("@TrainingLocationID",LocationID()));if(!string.IsNullOrWhiteSpace(txtTrainingID.Text)){q+=" AND SM.TrainingID LIKE @TrainingID";p.Add(new SqlParameter("@TrainingID","%"+txtTrainingID.Text.Trim()+"%"));}if(!string.IsNullOrWhiteSpace(txtBatch.Text)){q+=" AND TD.Batch LIKE @Batch";p.Add(new SqlParameter("@Batch","%"+txtBatch.Text.Trim()+"%"));}DateTime d;if(DateTime.TryParseExact(txtFrom.Text.Trim(),"dd-MM-yyyy",CultureInfo.InvariantCulture,DateTimeStyles.None,out d)){q+=" AND TRY_CONVERT(date,SM.SessionDate,105)>=@FromDate";p.Add(new SqlParameter("@FromDate",d));}if(DateTime.TryParseExact(txtTo.Text.Trim(),"dd-MM-yyyy",CultureInfo.InvariantCulture,DateTimeStyles.None,out d)){q+=" AND TRY_CONVERT(date,SM.SessionDate,105)<=@ToDate";p.Add(new SqlParameter("@ToDate",d));}q+=" ORDER BY TRY_CONVERT(date,SM.SessionDate,105) DESC,TRY_CONVERT(int,SM.SessionNo),SM.SessionID DESC";gvSession.DataSource=obj.GetDataTable(q,p.ToArray());gvSession.DataBind();}
protected void btnSearch_Click(object s,EventArgs e){BindGrid();}protected void btnReset_Click(object s,EventArgs e){txtTrainingID.Text="";txtBatch.Text="";txtFrom.Text="";txtTo.Text="";BindGrid();}
protected void gvSession_RowCommand(object s,GridViewCommandEventArgs e){if(e.CommandName!="View")return;GridViewRow row=(GridViewRow)((Control)e.CommandSource).NamingContainer;string sid=gvSession.DataKeys[row.RowIndex].Values["SessionID"].ToString();string tid=gvSession.DataKeys[row.RowIndex].Values["TrainingID"].ToString();Session["SessionID"]=sid;Session["TrainingID"]=tid;Response.Redirect("~/Manager/SessionReportDetails.aspx");}}}